import React, { useState } from 'react';
import { FeedbackContext } from './FeedbackContext';

const FeedbackForm = () => {
  const [feedback, setFeedback] = useState({
    course: '',
    instructor: '',
    rating: '',
    comments: '',
  });

  const { updateFeedback } = useContext(FeedbackContext);

  const handleSubmit = (event) => {
    event.preventDefault();
    updateFeedback(feedback);
  };

  const handleInputChange = (event) => {
    setFeedback((prevFeedback) => ({ ...prevFeedback, [event.target.name]: event.target.value }));
  };

  return (
    <form onSubmit={handleSubmit}>
      <label>
        Course:
        <input type="text" name="course" value={feedback.course} onChange={handleInputChange} />
      </label>
      <label>
        Instructor:
        <input type="text" name="instructor" value={feedback.instructor} onChange={handleInputChange} />
      </label>
      <label>
        Rating:
        <input type="number" name="rating" value={feedback.rating} onChange={handleInputChange} />
      </label>
      <label>
        Comments:
        <textarea name="comments" value={feedback.comments} onChange={handleInputChange} />
      </label>
      <button type="submit">Submit Feedback</button>
    </form>
  );
};

export default FeedbackForm;
```
