Here is a simple implementation of a pendulum simulation using HTML5 canvas and JavaScript. It allows the user to input the initial angle of the pendulum and then starts the simulation when the "Release" button is clicked.

This implementation uses the equations of motion for a simple pendulum to calculate the new angle and position of the pendulum at each time step. The time step is controlled using the `requestAnimationFrame` function, which schedules the next rendering of the pendulum when the current frame is finished.

```html
<!DOCTYPE html>
<html>
<head>
  <meta charset="UTF-8">
  <title>Pendulum Simulation</title>
  <style>
    body {
      margin: 0;
      font-family: Arial, sans-serif;
    }
    #canvas {
      border: 1px solid black;
    }
  </style>
</head>
<body>
  <canvas id="canvas" width="400" height="400"></canvas>
  <input id="angle" type="number" value="45" />
  <button id="release">Release</button>
  <script>
    const canvas = document.getElementById('canvas');
    const ctx = canvas.getContext('2d');
    ctx.fillStyle = 'white';
    ctx.fillRect(0, 0, canvas.width, canvas.height);

    let initialAngle = 0;
    let RELEASED = false;

    document.getElementById('release').addEventListener('click', () => {
      RELEASED = true;
      initialAngle = parseInt(document.getElementById('angle').value);
    });

    let g = 9.81; // acceleration due to gravity
    let l = 100; // length of the pendulum
    let dt = 0.1; // time step

    function update() {
      if (RELEASED) {
        let angle = initialAngle;
        let velocity = 0;
        let t = 0;

        function iterate() {
          velocity += (-g / l) * Math.sin(angle) * dt;
          angle += velocity * dt;

          ctx.clearRect(0, 0, canvas.width, canvas.height);
          ctx.fillStyle = 'black';
          ctx.beginPath();
          ctx.arc(canvas.width / 2, canvas.height / 2, l, 0, 2 * Math.PI, true);
          ctx.fillStyle = 'black';
          ctx.fill();
          ctx.fillStyle = 'white';
          ctx.beginPath();
          ctx.arc(canvas.width / 2, canvas.height / 2, l, -Math.PI / 2, angle, true);
          ctx.fill();

          if (Math.abs(velocity) < 0.1) {
            RELEASED = false;
          } else {
            requestAnimationFrame(iterate);
          }
          t += dt;
        }
        iterate();
      }
    }

    setInterval(update, 16); // update 60 times per second
  </script>
</body>
</html>
```

