	params := &ec2.DescribeSnapshotsInput{
		Filters: []*ec2.Filter{
			{
				Name: aws.String("tag:backup_type"),
				Values: []*string{
					aws.String("monthly"),
					aws.String("daily"),
					aws.String("weekly"),
					aws.String("yearly"),
				},
			},
		},
	}

	resp, err := ec2Client.DescribeSnapshots(params)
	if err != nil {
		log.Println(err)
		return nil, err
	}

