    def move(self):
        moves = {
            UP: (-10, 0),
            DOWN: (10, 0),
            LEFT: (0, -10),
            RIGHT: (0, 10),
            UP + DOWN: (0, 10),
            LEFT + RIGHT: (-10, 0),
            UP + RIGHT: (-10, 10),
            DOWN + RIGHT: (10, 10),
            UP + LEFT: (-10, -10),
            DOWN + LEFT: (10, -10)
        }
        food_pos = self.find_food()
        self.direction, self.body, self.head = self.nextLine(self.direction, self.body, self.head, moves[self.direction], food_pos)

    def nextLine(self, direction, body, head, move, food_pos):
        new_head = (head[0] + move[0], head[1] + move[1])
        new_body = [(0, 0, 'head') for _ in body]  # reset body colors
        if new_head in body:
            new_head = body[-1]
        else:
            new_head = new_head
        for i in range(len(body) - 1, 0, -1):
            new_body[i] = new_body[i - 1]
        new_body[0] = new_head
        if new_head == food_pos:
            return direction, new_body, new_head
        else:
