#include <pigpio.h>

int main() {
    // Initialize the pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        return 1;
    }

    // Set GPIO pin 12 as an output
    gpioSetup(12, PI_OUTPUT);

    // Set the initial state of the pin to LOW (0V)
    gpioWrite(12, PI_LOW);

    // Wait for 1 second
    delay(1000);

    // Set the pin to HIGH (3.3V)
    gpioWrite(12, PI_HIGH);

    // Wait for 1 second
    delay(1000);

    // Set the pin back to LOW (0V)
    gpioWrite(12, PI_LOW);

    // Clean up
    gpioTerminate();
    return 0;
}
```
